<section><h1>Custom order #<?=$order['id']?></h1><p>Status <?=H::e($order['status'])?> · payment <?=H::e($order['payment_status'])?> <?=H::money($order['total'])?> · buyer <?=H::e($order['buyer_name'])?> · seller <?=H::e($order['display_name'])?></p><?php if($order['manual_review_required']):?><p>Dispute/payment review: <?=H::e($order['manual_review_reason'])?></p><?php endif?><h2>Message reports / disputes</h2><?php if(!$reports):?><p>No linked conversation reports.</p><?php else:foreach($reports as $report):?><p><a href="/admin/message-reports/<?=$report['id']?>">Report #<?=$report['id']?></a> — <?=H::e($report['reason'])?> (<?=H::e($report['status'])?>)</p><?php endforeach;endif?><h2>Submitted brief</h2><?php foreach($brief as $k=>$v):?><p><strong><?=H::e($k)?>:</strong> <?=H::e(is_array($v)?json_encode($v):$v)?></p><?php endforeach?><h2>Delivery state</h2><?php foreach($files as $f):?><p><?=H::e($f['file_kind'])?> — <?=H::e($f['original_name'])?></p><?php endforeach?></section>
